import { PillNav } from "solen-design/react";

const items = [
  { label: "Home", href: "#" },
  { label: "Work", href: "#work" },
  { label: "About", href: "#about" },
  { label: "Contact", href: "#contact" }
];

<PillNav
  items={items}
  theme="light"
  layout="split"
  size="md"
  surface="glass"
  itemStyle="plain"
  hoverEffect="fill"
  indicator="dot"
  bounce={0.3}
  stretch={0.5}
  intro={true}
  onItemClick={(item, index) => console.log(index, item.label)}
/>
